    eq('one tax line for the whole order', leds.map((l) => [l.vat_rule, l.amount]), [['taxable', 547000]]);
    box = await sql('SELECT op, payload FROM shop_outbox WHERE order_id = $1 ORDER BY id', [o.id]);
    eq('ActiveCampaign: the product’s tag, the add-on’s, the option’s', box.filter((b) => b.op === 'tag_add').map((b) => b.payload.tag), ['purchased_e2e_opt', 'purchased_e2e_scripts', 'e2e_vip']);
    eq('ORDER_PRODUCT names the option', box.find((b) => b.op === 'fields').payload.fields.ORDER_PRODUCT, '옵션 테스트 상품 · VIP');
    html = await (await get(`/checkout/complete?o=${o.token}`)).text();
    check('thank-you page names the option', html.includes('옵션 테스트 상품 · VIP') && html.includes('₩547,000'));
    const listedOrder = (await (await fetch(`${base}/api/admin?action=shop-orders&product=${optP.id}`)).json()).orders.find((x) => x.id === o.id);
    eq('the admin order list has the option', listedOrder && listedOrder.price_option.label, 'VIP');
    r = await postJson('/api/shop?action=order', abroad(70, { slug: 'e2e-opt', option: kVip }), from());
    o = await orderOf('abroad70@example.com');
    eq('PayPal: the option’s dollar price', [r.status, o.total, fake.paypal.get(o.provider_request).body.purchase_units[0].amount.value], [200, 40000, '400.00']);
    r = await get(`/__fake/paypal/do?id=${o.provider_request}&act=approve`);
    await (await get(r.headers.get('location').replace(base, ''))).text();
    leds = await sql('SELECT amount, vat_rule FROM shop_ledger WHERE order_id = $1 ORDER BY id', [o.id]);
    eq('paid, zero-rated in dollars', [(await orderOf('abroad70@example.com')).status, leds.map((l) => [l.vat_rule, l.amount])], ['paid', [['zero', 40000]]]);
    res = await admin('shop-product-save', { ...optInput, id: optP.id, price_options: [typedBack[0], { label: 'Premium', price_krw: '900000', price_usd: '700', compare_krw: '', compare_usd: '', tag: '', note: '' }] });
    r = await postJson('/api/shop?action=order', optBuyer(73), from());
    eq('an option removed since the page was opened: refused', [r.status, (await r.json()).error], [409, 'option_unavailable']);
    o = await orderOf('buyer70@example.com');
    eq('…and the paid order still has its own copy of it', o.price_option.label, 'VIP');

    group('Payment method and address country');
    const swap = buyer(74, { slug: 'e2e-opt', option: kBasic, currency: 'USD', shown_currency: 'KRW', country: 'US', phone_cc: 'US', phone: '(415) 555-0123', postcode: '94105', address1: '1 Market St, San Francisco' });
    r = await postForm('/api/shop?action=order', swap, from());
    html = await r.text();
    check('without JavaScript, switching to PayPal first shows the dollar prices', r.status === 409 && html.includes('결제 방법에 맞춰 금액을 다시 보여 드려요') && html.includes('$250 결제하기') && html.includes('id="co-method-paypal" value="USD" checked>') && html.includes('value="1 Market St, San Francisco"') && html.includes('<option value="US" selected>'));
    eq('…and creates no order until confirmed', await count('shop_orders o JOIN shop_customers c ON c.id = o.customer_id', 'c.email = $1', ['buyer74@example.com']), 0);
    r = await postForm('/api/shop?action=order', { ...swap, shown_currency: 'USD' }, from());
    check('confirmed: to PayPal', r.status === 303 && String(r.headers.get('location')).includes('/__fake/paypal/'));
    r = await postJson('/api/shop?action=order', abroad(75, { country: 'KR', phone: '010-1234-5678', phone_cc: 'KR', postcode: '48095', address1: '부산 해운대구 중동1로17번길 15-1' }), from());
    o = await orderOf('abroad75@example.com');
    eq('PayPal with a Korean address', [r.status, o.billing.country, o.billing.postcode], [200, 'KR', '48095']);
    r = await postJson('/api/shop?action=order', abroad(76, { country: 'KR', postcode: '' }), from());
    eq('a Korean address needs its postcode, whichever the method', [r.status, ((await r.json()).fields || {}).postcode], [422, 'postcode_required']);
    r = await postJson('/api/shop?action=order', buyer(77, { country: 'AU', phone_cc: 'AU', phone: '0412 345 678', postcode: '', address1: '1 George St, Sydney NSW' }), from());
    o = await orderOf('buyer77@example.com');
    eq('card from abroad: the country kept, no postcode needed', [r.status, o.currency, o.billing.country, o.billing.phone], [200, 'KRW', 'AU', '+61412345678']);


    // ---------- refunds (phase 3) ----------
    const refundsOf = (orderId) => sql('SELECT * FROM shop_refunds WHERE order_id = $1 ORDER BY id', [orderId]);
    const ledgerSum = async (orderId, kind) => (await one(`SELECT COALESCE(sum(amount), 0)::int AS n FROM shop_ledger WHERE order_id = $1 AND kind = $2`, [orderId, kind])).n;
    const tagsOf = async (orderId) => (await sql(`SELECT op, payload->>'tag' AS tag FROM shop_outbox WHERE order_id = $1 AND op IN ('tag_add', 'tag_remove') ORDER BY id`, [orderId])).map((x) => `${x.op === 'tag_add' ? '+' : '-'}${x.tag}`);
    const refundApi = (action, body) => fetch(`${base}/api/admin?action=${action}`, { method: 'POST', headers: { 'Content-Type': 'application/json', ...origin }, body: JSON.stringify(body) });
    // A KRW order paid through the fake CiderPay. → { o, rid }
    async function paidKrw(n) {
      const res = await (await postJson('/api/shop?action=order', buyer(n), from())).json();
      const rid = ridOf(res.redirect);
      await fake.notifyCiderpay(rid);
      return { o: await orderOf(`buyer${n}@example.com`), rid };
    }
    async function paidUsd(n) {
      const res = await (await postJson('/api/shop?action=order', abroad(n), from())).json();
      const pid = new URL(res.redirect).searchParams.get('id');
      const back = (await get(`/__fake/paypal/do?id=${pid}&act=approve`)).headers.get('location');
      await get(back.replace(base, ''));
      return { o: await orderOf(`abroad${n}@example.com`), pid };
    }
    const calls = () => fake.refundCalls.length;
    const adminGet = async (action, params) => (await fetch(`${base}/api/admin?action=${action}&${new URLSearchParams(params)}`)).json();

    group('Refunds: CiderPay, part then the rest');
    let { o: ro, rid: rrid } = await paidKrw(201);
    const rpay = await one(`SELECT * FROM shop_payments WHERE order_id = $1 AND kind = 'payment'`, [ro.id]);
    let rdetail = await adminGet('shop-order', { id: ro.id });
    eq('the admin offers the whole payment', rdetail.refundable, [{ payment_id: rpay.id, provider: 'ciderpay', amount: 220000, left: 220000 }]);
    r = await refundApi('shop-refund', { order: ro.id, amount: 20000, reason: '' });
    eq('a reason is required', r.status, 400);
    let c0 = calls();
    r = await refundApi('shop-refund', { order: ro.id, amount: 20000, reason: '일부 환불 테스트' });
    body = await r.json();
    eq('partial refund: done', [r.status, body.status], [200, 'done']);
    eq('CiderPay asked for a partial cancel of that payment', fake.refundCalls.slice(c0).map((x) => [x.path, x.body.rangeType, x.body.cancelPrice, x.body.orderNo, x.body.token, x.body.cancelMessage]),
      [['/oapi/payment/cancel', 'PART', 20000, 'CP' + rrid, 'FT' + rrid, '일부 환불 테스트']]);
    ro = await orderOf('buyer201@example.com');
    eq('order: partly refunded, nothing left reserved', [ro.status, ro.paid_total, ro.refunded_total, ro.refund_pending], ['partially_refunded', 220000, 20000, 0]);
    let rp = await one(`SELECT * FROM shop_payments WHERE order_id = $1 AND kind = 'refund'`, [ro.id]);
    eq('a refund payment, pointing at the payment it gives back', [rp.provider, rp.amount, rp.currency, rp.refund_of], ['ciderpay', 20000, 'KRW', rpay.id]);
    eq('negative tax lines for it, split like the sale', await sql(`SELECT amount, supply, vat, vat_rule, note FROM shop_ledger WHERE payment_id = $1`, [rp.id]), [{ amount: -20000, supply: -18182, vat: -1818, vat_rule: 'taxable', note: '일부 환불 테스트' }]);
    eq('ActiveCampaign: refund_partial tag, purchase tags kept', (await tagsOf(ro.id)).slice(-1), ['+refund_partial_eft']);
    eq('…and the refund fields', (await one(`SELECT payload->'fields' AS f FROM shop_outbox WHERE order_id = $1 AND op = 'fields' ORDER BY id DESC LIMIT 1`, [ro.id])).f.REFUND_AMOUNT, '₩20,000');
    n = await fake.notifyCiderpay(rrid, { paymentState: 'CANCEL' });
    eq('CiderPay’s own notice of it: acknowledged, nothing recorded twice', [n.status, JSON.parse(n.body).outcome, await count('shop_payments', `order_id = $1 AND kind = 'refund'`, [ro.id])], [200, 'duplicate', 1]);
    check('…and noted on the refund', (await refundsOf(ro.id))[0].notice_at !== null);
    r = await refundApi('shop-refund', { order: ro.id, amount: 200001, reason: 'too much' });
    eq('more than what is left: refused before calling CiderPay', [r.status, /more than what is left/.test((await r.json()).error), calls()], [400, true, c0 + 1]);
    r = await refundApi('shop-refund', { order: ro.id, amount: 200000, reason: '나머지 환불' });
    eq('the rest: done', (await r.json()).status, 'done');
    eq('…as a partial cancel (an ALL cancel would give back the first part twice)', [fake.refundCalls.at(-1).body.rangeType, fake.refundCalls.at(-1).body.cancelPrice], ['PART', 200000]);
    ro = await orderOf('buyer201@example.com');
    eq('order: refunded in full', [ro.status, ro.refunded_total, ro.refund_pending], ['refunded', 220000, 0]);
    eq('tax lines: the sale and two refunds cancel out', [await ledgerSum(ro.id, 'sale'), await ledgerSum(ro.id, 'refund')], [220000, -220000]);
    eq('ActiveCampaign: refund tag added, purchase tags removed', (await tagsOf(ro.id)).slice(-3), ['+refund_eft', '-purchased_eft', '-customer']);
    r = await refundApi('shop-refund', { order: ro.id, amount: 1, reason: 'again' });
    eq('a refunded order can’t be refunded again', r.status, 400);
    eq('nothing left to offer in the admin', (await adminGet('shop-order', { id: ro.id })).refundable, []);

    group('Refunds: CiderPay settled → cancel request → confirmed by its notice');
    ({ o: ro, rid: rrid } = await paidKrw(202));
    fake.modes.ciderpayCancel = 'settled';
    c0 = calls();
    body = await (await refundApi('shop-refund', { order: ro.id, amount: 220000, reason: '환불 요청 (14일 이내)' })).json();
    eq('accepted as a request', body.status, 'requested');
    eq('cancel tried first, then the cancel request, for the whole payment', fake.refundCalls.slice(c0).map((x) => [x.path, x.body.rangeType]), [['/oapi/payment/cancel', 'ALL'], ['/oapi/payment/cancelRequest', 'ALL']]);
    ro = await orderOf('buyer202@example.com');
    eq('order: refund requested, amount reserved, nothing refunded yet', [ro.status, ro.refunded_total, ro.refund_pending, await ledgerSum(ro.id, 'refund')], ['refund_requested', 0, 220000, 0]);
    r = await refundApi('shop-refund', { order: ro.id, amount: 1000, reason: 'while waiting' });
    eq('nothing more can be refunded while it waits', r.status, 400);
    n = await fake.notifyCiderpay(rrid, { paymentState: 'CANCEL' });
    eq('CiderPay’s CANCEL notice confirms it', [n.status, JSON.parse(n.body).outcome], [200, 'refunded']);
    ro = await orderOf('buyer202@example.com');
    eq('order: refunded, reservation released', [ro.status, ro.refunded_total, ro.refund_pending, await ledgerSum(ro.id, 'refund')], ['refunded', 220000, 0, -220000]);
    n = await fake.notifyCiderpay(rrid, { paymentState: 'CANCEL' });
    eq('the notice again: duplicate', [JSON.parse(n.body).outcome, await count('shop_payments', `order_id = $1 AND kind = 'refund'`, [ro.id])], ['duplicate', 1]);
    fake.modes.ciderpayCancel = 'ok';

    group('Refunds: CiderPay refuses, or never answers');
    ({ o: ro, rid: rrid } = await paidKrw(203));
    fake.modes.ciderpayCancel = 'refuse';
    body = await (await refundApi('shop-refund', { order: ro.id, amount: 1000, reason: 'r' })).json();
    eq('refused: said so, nothing changed', [body.status, /refused/.test(body.message)], ['failed', true]);
    ro = await orderOf('buyer203@example.com');
    eq('order untouched, reservation released', [ro.status, ro.refunded_total, ro.refund_pending, await ledgerSum(ro.id, 'refund')], ['paid', 0, 0, 0]);
    fake.modes.ciderpayCancel = 'down';
    body = await (await refundApi('shop-refund', { order: ro.id, amount: 1000, reason: 'r' })).json();
    eq('no answer (server error): to check by hand', body.status, 'check');
    ro = await orderOf('buyer203@example.com');
    eq('order: refund requested, the amount stays reserved', [ro.status, ro.refund_pending], ['refund_requested', 1000]);
    let rf = (await refundsOf(ro.id)).at(-1);
    body = await (await refundApi('shop-refund-resolve', { refund: rf.id, happened: false })).json();
    ro = await orderOf('buyer203@example.com');
    eq('“It didn’t”: failed, released, back to paid', [body.status, ro.status, ro.refund_pending, ro.refunded_total], ['failed', 'paid', 0, 0]);
    fake.modes.ciderpayCancel = 'hang';
    body = await (await refundApi('shop-refund', { order: ro.id, amount: 1000, reason: 'r' })).json();
    eq('connection dropped: to check by hand', body.status, 'check');
    rf = (await refundsOf(ro.id)).at(-1);
    body = await (await refundApi('shop-refund-resolve', { refund: rf.id, happened: true })).json();
    ro = await orderOf('buyer203@example.com');
    eq('“It went through”: recorded', [body.status, ro.status, ro.refunded_total, ro.refund_pending, await ledgerSum(ro.id, 'refund')], ['done', 'partially_refunded', 1000, 0, -1000]);
    r = await refundApi('shop-refund-resolve', { refund: rf.id, happened: true });
    eq('resolving it twice is refused', r.status, 400);
    fake.modes.ciderpayCancel = 'ok';

    group('Refunds: made at CiderPay, recorded by hand');
    ({ o: ro, rid: rrid } = await paidKrw(204));
    n = await fake.notifyCiderpay(rrid, { paymentState: 'CANCEL' });
    eq('a cancel made in CiderPay’s dashboard: flagged for a person (the notice doesn’t say how much)', [n.status, JSON.parse(n.body).outcome], [200, 'attention']);
    ro = await orderOf('buyer204@example.com');
    eq('…the order is not changed by itself', [ro.status, ro.refunded_total], ['paid', 0]);
    c0 = calls();
    body = await (await refundApi('shop-refund-record', { order: ro.id, amount: 220000, reason: 'CiderPay 대시보드에서 취소' })).json();
    ro = await orderOf('buyer204@example.com');
    eq('recorded without calling CiderPay', [body.status, calls(), ro.status, ro.refunded_total, await ledgerSum(ro.id, 'refund')], ['done', c0, 'refunded', 220000, -220000]);
    eq('…and marked as recorded by hand', [(await refundsOf(ro.id))[0].origin, (await refundsOf(ro.id))[0].by], ['recorded', 'dev']);
    n = await fake.notifyCiderpay(rrid, { paymentState: 'CANCEL', orderNo: 'CP-OTHER' });
    eq('a cancel notice naming another payment: refused', [n.status, JSON.parse(n.body).message], [400, 'rejected']);
    n = await fake.notifyCiderpay(rrid, { paymentState: 'CANCEL', var2: 'x'.repeat(32) });
    eq('a forged cancel notice: refused', n.status, 400);

    group('Refunds: two clicks at once');
    ({ o: ro } = await paidKrw(205));
    const both = await Promise.all([1, 2].map(() => refundApi('shop-refund', { order: ro.id, amount: 220000, reason: 'double click' }).then((x) => x.json().then((j) => [x.status, j.status || j.error]))));
    ro = await orderOf('buyer205@example.com');
    eq('only one refund went out', [both.filter((x) => x[1] === 'done').length, ro.refunded_total, ro.refund_pending, await count('shop_payments', `order_id = $1 AND kind = 'refund'`, [ro.id])], [1, 220000, 0, 1]);
    eq('the database refuses refunds above what was paid', await count('shop_orders', 'refunded_total + refund_pending > paid_total', []), 0);

    group('Refunds: podcast access ends on a full refund');
    const show = await one(`INSERT INTO shows (slug, title, ac_tag_prefix) VALUES ('e2e-refund-show', 'E2E', 'podcast_e2e') RETURNING id`);
    const cohort = await one(`INSERT INTO cohorts (show_id, name, ac_tag, start_date) VALUES ($1, 'E2E 1기', 'purchased_eft', '2026-01-01') RETURNING id`, [show.id]);
    const student = await one(`INSERT INTO students (email, token, name) VALUES ('buyer206@example.com', 'e2erefundtoken000000aa', '김지연') RETURNING id`);
    await sql(`INSERT INTO enrollments (student_id, cohort_id, source) VALUES ($1, $2, 'webhook')`, [student.id, cohort.id]);
    ({ o: ro } = await paidKrw(206));
    await refundApi('shop-refund', { order: ro.id, amount: 1000, reason: 'partial' });
    eq('a partial refund keeps access', (await one(`SELECT status FROM enrollments WHERE student_id = $1`, [student.id])).status, 'active');
    await refundApi('shop-refund', { order: ro.id, amount: 219000, reason: 'rest' });
    eq('the full refund revokes it', (await one(`SELECT status FROM enrollments WHERE student_id = $1`, [student.id])).status, 'revoked');
    check('…and says so on the order', (await count('shop_callbacks', `order_id = $1 AND outcome = 'access_revoked'`, [ro.id])) === 1);

    group('Refunds: PayPal');
    let { o: uo, pid } = await paidUsd(201);
    c0 = calls();
    body = await (await refundApi('shop-refund', { order: uo.id, amount: 1000, reason: 'partial $10' })).json();
    eq('partial PayPal refund: done', body.status, 'done');
    const ppCall = fake.refundCalls.at(-1);
    rf = (await refundsOf(uo.id))[0];
